const wallTex = canvasTex(1024, 256, (x, w, h) => {
  const g = x.createLinearGradient(0, 0, 0, h); g.addColorStop(0, '#202124'); g.addColorStop(0.55, '#141517'); g.addColorStop(1, '#08080a');
  x.fillStyle = g; x.fillRect(0, 0, w, h);
  for (const cx of [0.355, 0.645]) { const r = x.createRadialGradient(cx*w, 0, 0, cx*w, 0, w*0.24); r.addColorStop(0, 'rgba(255,255,255,0.10)'); r.addColorStop(1, 'rgba(255,255,255,0)'); x.fillStyle = r; x.fillRect(0, 0, w, h); }
  x.fillStyle = 'rgba(0,0,0,0.35)'; for (let i = 1; i < 12; i++) x.fillRect(Math.round(i*w/12), 0, 2, h);
  const e = x.createLinearGradient(0, 0, w, 0); e.addColorStop(0, 'rgba(0,0,0,0.75)'); e.addColorStop(0.22, 'rgba(0,0,0,0)'); e.addColorStop(0.78, 'rgba(0,0,0,0)'); e.addColorStop(1, 'rgba(0,0,0,0.75)');
  x.fillStyle = e; x.fillRect(0, 0, w, h);
});
const sideTex = canvasTex(256, 128, (x, w, h) => {
  const g = x.createLinearGradient(0, 0, 0, h); g.addColorStop(0, '#111113'); g.addColorStop(1, '#050506'); x.fillStyle = g; x.fillRect(0, 0, w, h);
});
const ceilTex = canvasTex(512, 512, (x, w, h) => {
  x.fillStyle = '#060607'; x.fillRect(0, 0, w, h);
  // light spill on the slab above each panel (u = x, v = z)
  const Lz = GAR.zFront - GAR.zBack, cy = (1 - (PANEL.z - GAR.zBack) / Lz) * h;
  for (const px of PANEL.xs) { const cx = (px / GAR.W + 0.5) * w;
    const r = x.createRadialGradient(cx, cy, 0, cx, cy, w*0.2); r.addColorStop(0, 'rgba(255,255,255,0.10)'); r.addColorStop(1, 'rgba(255,255,255,0)'); x.fillStyle = r; x.fillRect(0, 0, w, h); }
});
const floorTex = canvasTex(1024, 1024, (x, w, h) => {
  x.fillStyle = '#0b0b0c'; x.fillRect(0, 0, w, h);
  for (let i = 0; i < 260; i++) { const cx = rnd()*w, cy = rnd()*h, r = 30 + rnd()*150, d = rnd() > 0.5;
    const g = x.createRadialGradient(cx, cy, 0, cx, cy, r); g.addColorStop(0, d ? 'rgba(0,0,0,0.20)' : 'rgba(255,255,255,0.045)'); g.addColorStop(1, 'rgba(0,0,0,0)'); x.fillStyle = g; x.fillRect(cx - r, cy - r, r*2, r*2); }
  x.fillStyle = 'rgba(0,0,0,0.45)'; for (let i = 1; i < 6; i++) { x.fillRect(Math.round(i*w/6), 0, 2, h); x.fillRect(0, Math.round(i*h/6), w, 2); }
});
const wetTex = canvasTex(512, 512, (x, w, h) => {      // alpha: lower = wetter = more reflection
  x.fillStyle = 'rgb(251,251,251)'; x.fillRect(0, 0, w, h);
  for (let i = 0; i < 20; i++) { const cx = rnd()*w, cy = rnd()*h, r = 9 + rnd()*26;
    const g = x.createRadialGradient(cx, cy, 0, cx, cy, r); g.addColorStop(0, 'rgba(150,150,150,0.8)'); g.addColorStop(0.6, 'rgba(150,150,150,0.5)'); g.addColorStop(1, 'rgba(150,150,150,0)'); x.fillStyle = g; x.fillRect(cx - r, cy - r, r*2, r*2); }
});
wetTex.colorSpace = THREE.NoColorSpace;

function buildGarage(target, rig, forEnv){
  const L = GAR.zFront - GAR.zBack, zc = (GAR.zFront + GAR.zBack) / 2;
  const basic = (o) => new THREE.MeshBasicMaterial(o);
  // floor
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(GAR.W, L),
    forEnv ? basic({ color:'#101012' })
           : new THREE.MeshStandardMaterial({ map:floorTex, alphaMap:wetTex, roughness:0.62, metalness:0, envMapIntensity:0.1, transparent:true, opacity:0.985 }));
  floor.rotation.x = -Math.PI/2; floor.position.z = zc; floor.renderOrder = -2; floor.receiveShadow = !forEnv; target.add(floor);
  if (!forEnv) for (const t of [floorTex, wetTex, wallTex, sideTex, ceilTex]) { try { renderer.initTexture(t); } catch (e) {} }
  // back wall + side walls
  const back = new THREE.Mesh(new THREE.PlaneGeometry(GAR.W, GAR.H), basic(forEnv ? { color:'#1b1c1e' } : { map:wallTex }));
  back.position.set(0, GAR.H/2, GAR.zBack); target.add(back);
  for (const s of [-1, 1]) { const w = new THREE.Mesh(new THREE.PlaneGeometry(L, GAR.H), basic(forEnv ? { color:'#0c0c0d' } : { map:sideTex }));
    w.rotation.y = -s * Math.PI/2; w.position.set(s * GAR.W/2, GAR.H/2, zc); target.add(w); }
  // ceiling slab + light panels (in the rig, so they can lift out of the way of a high camera)
  const ceil = new THREE.Mesh(new THREE.PlaneGeometry(GAR.W, L), basic(forEnv ? { color:'#070708' } : { map:ceilTex }));
  ceil.rotation.x = Math.PI/2; ceil.position.set(0, GAR.H, zc); rig.add(ceil);
  rig.add(tubes(GAR.lightY, forEnv ? 0.03 : 0.034, forEnv ? 7.5 : 2.2, false));
  { const tm = basic({ color:new THREE.Color(1, 1, 1).multiplyScalar(forEnv ? 6 : 2.0), toneMapped:false, fog:false });
    const post = basic({ color:'#141416' });
    const col = (x, z, h0, h1) => { const t = new THREE.Mesh(new THREE.CylinderGeometry(0.024, 0.024, h1 - h0, 10), tm); t.position.set(x, (h0 + h1) / 2, z); target.add(t);
      if (!forEnv) { const pm = new THREE.Mesh(new THREE.BoxGeometry(0.07, GAR.H, 0.07), post); pm.position.set(x + Math.sign(x) * 0.09, GAR.H / 2, z); target.add(pm); } };
    for (const sx of [-1, 1]) for (const z of [-2.2, -4.0, -5.8]) { col(sx * 4.3, z, 0.35, 1.55); col(sx * 4.3, z, 1.72, 2.92); col(sx * 4.48, z, 0.35, 1.55); col(sx * 4.48, z, 1.72, 2.92); }
    for (const sx of [-1, 1]) { const top = new THREE.Mesh(new THREE.CylinderGeometry(0.024, 0.024, 3.4, 10), tm); top.rotation.x = Math.PI / 2; top.position.set(sx * 4.39, 3.05, -4.0); target.add(top); } }
  if (!forEnv) {
    const cab = basic({ color:'#1d1e20' });
    for (const px of PANEL.xs) for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      const c = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, GAR.H - GAR.lightY, 5), cab);
      c.position.set(px + sx*(PANEL.w/2 - 0.3), (GAR.H + GAR.lightY)/2, PANEL.z + sz*(PANEL.d/2 - 0.5)); rig.add(c); }
    // soft reflection of the panels in the wet floor: three widening, fading layers read as a blur
    for (const [t, b] of [[0.08, 0.1], [0.22, 0.04], [0.42, 0.018]]) target.add(tubes(-GAR.lightY, t, b, true));
  }
}
buildGarage(garage, ceilRig, false);

